interface.signature:
interface AnswerDisplayProps {
  response: RainCheckResponse
  searchedLocation: string
}

function AnswerDisplay({ response, searchedLocation }: AnswerDisplayProps): JSX.Element

interface RainCheckResponse {
  location: string
  lat: number
  lon: number
  willRain: false           // NO answer indicator
  probability: number        // e.g., 35 (always <50%)
  closeCall: boolean         // true if 40-49%, false otherwise
  // rainWindows, peakTime, intensity, amount, safeWindows NOT present for NO answers
  forecast: Array<...>
}

interface CloseCallBadgeProps {
  show: boolean
}

function CloseCallBadge({ show }: CloseCallBadgeProps): JSX.Element | null
